create table public.roles (id uuid primary key default gen_random_uuid(), key citext not null unique, name text not null, description text not null default '', is_system boolean not null default false, created_at timestamptz not null default timezone('utc', now()), updated_at timestamptz not null default timezone('utc', now()));
create table public.permissions (id uuid primary key default gen_random_uuid(), key citext not null unique, module text not null, description text not null default '', created_at timestamptz not null default timezone('utc', now()), updated_at timestamptz not null default timezone('utc', now()));
create table public.role_permissions (role_id uuid not null references public.roles(id) on delete restrict, permission_id uuid not null references public.permissions(id) on delete restrict, created_at timestamptz not null default timezone('utc', now()), primary key(role_id, permission_id));
create table public.user_roles (id uuid primary key default gen_random_uuid(), user_id uuid not null references public.profiles(id) on delete cascade, role_id uuid not null references public.roles(id) on delete restrict, campus_id uuid references public.campuses(id) on delete restrict, granted_by uuid references public.profiles(id) on delete set null, expires_at timestamptz, created_at timestamptz not null default timezone('utc', now()), updated_at timestamptz not null default timezone('utc', now()), unique nulls not distinct(user_id, role_id, campus_id));
create table public.feature_registry (id uuid primary key default gen_random_uuid(), key citext not null unique, name text not null, description text not null default '', module_group text not null, icon text, route text, sort_order integer not null default 0, is_enabled boolean not null default true, created_at timestamptz not null default timezone('utc', now()), updated_at timestamptz not null default timezone('utc', now()), constraint feature_route_absolute check (route is null or route like '/%'));
create table public.role_features (role_id uuid not null references public.roles(id) on delete restrict, feature_id uuid not null references public.feature_registry(id) on delete restrict, created_at timestamptz not null default timezone('utc', now()), primary key(role_id, feature_id));
create index user_roles_user_scope_idx on public.user_roles(user_id, campus_id, expires_at);
create index role_permissions_permission_id_idx on public.role_permissions(permission_id); create index role_features_feature_id_idx on public.role_features(feature_id); create index feature_registry_enabled_order_idx on public.feature_registry(is_enabled, sort_order);
create trigger roles_set_updated_at before update on public.roles for each row execute function public.set_updated_at(); create trigger permissions_set_updated_at before update on public.permissions for each row execute function public.set_updated_at(); create trigger user_roles_set_updated_at before update on public.user_roles for each row execute function public.set_updated_at(); create trigger feature_registry_set_updated_at before update on public.feature_registry for each row execute function public.set_updated_at();
create or replace function public.has_permission(permission_key text, scope_campus_id uuid default null) returns boolean language sql stable security definer set search_path = public as $$ select exists(select 1 from public.user_roles ur join public.role_permissions rp on rp.role_id=ur.role_id join public.permissions p on p.id=rp.permission_id where ur.user_id=auth.uid() and p.key=permission_key and (ur.expires_at is null or ur.expires_at > timezone('utc',now())) and (scope_campus_id is null or ur.campus_id is null or ur.campus_id=scope_campus_id)); $$;
create or replace function public.has_feature(feature_key text, scope_campus_id uuid default null) returns boolean language sql stable security definer set search_path = public as $$ select exists(select 1 from public.user_roles ur join public.role_features rf on rf.role_id=ur.role_id join public.feature_registry f on f.id=rf.feature_id where ur.user_id=auth.uid() and f.key=feature_key and f.is_enabled and (ur.expires_at is null or ur.expires_at > timezone('utc',now())) and (scope_campus_id is null or ur.campus_id is null or ur.campus_id=scope_campus_id)); $$;
alter table public.roles enable row level security; alter table public.permissions enable row level security; alter table public.role_permissions enable row level security; alter table public.user_roles enable row level security; alter table public.feature_registry enable row level security; alter table public.role_features enable row level security;
create policy roles_read on public.roles for select to authenticated using (true); create policy permissions_read on public.permissions for select to authenticated using (true); create policy role_permissions_read on public.role_permissions for select to authenticated using (true); create policy user_roles_read on public.user_roles for select to authenticated using (user_id=auth.uid() or public.has_permission('rbac.manage',campus_id)); create policy feature_registry_read on public.feature_registry for select to authenticated using (true); create policy role_features_read on public.role_features for select to authenticated using (true);
create policy roles_admin on public.roles for all to authenticated using (public.has_permission('rbac.manage')) with check (public.has_permission('rbac.manage')); create policy permissions_admin on public.permissions for all to authenticated using (public.has_permission('rbac.manage')) with check (public.has_permission('rbac.manage')); create policy role_permissions_admin on public.role_permissions for all to authenticated using (public.has_permission('rbac.manage')) with check (public.has_permission('rbac.manage')); create policy user_roles_admin on public.user_roles for all to authenticated using (public.has_permission('rbac.manage',campus_id)) with check (public.has_permission('rbac.manage',campus_id)); create policy feature_registry_admin on public.feature_registry for all to authenticated using (public.has_permission('features.manage')) with check (public.has_permission('features.manage')); create policy role_features_admin on public.role_features for all to authenticated using (public.has_permission('features.manage')) with check (public.has_permission('features.manage'));
grant execute on function public.has_permission(text,uuid), public.has_feature(text,uuid) to authenticated;
